setup:
$ErrorActionPreference = 'Stop'
# Plants the 5 problems. Every problem is forced into place, so a VM someone already hardened
# still starts the practice with all 5.
function New-Pw { (-join ((48..57) + (65..90) + (97..122) | Get-Random -Count 14 | ForEach-Object { [char]$_ })) + 'Aa1!' }
foreach ($u in 'alice', 'bob', 'hacker') {
    $pw = ConvertTo-SecureString (New-Pw) -AsPlainText -Force
    if (Get-LocalUser -Name $u -ErrorAction SilentlyContinue) {
        Set-LocalUser -Name $u -Password $pw
    } else {
        New-LocalUser -Name $u -Password $pw -PasswordNeverExpires | Out-Null
    }
    Add-LocalGroupMember -SID 'S-1-5-32-545' -Member $u -ErrorAction SilentlyContinue   # Users
}
# 1) hacker exists (unauthorized). 2) bob is an administrator, but only you should be.
Add-LocalGroupMember -SID 'S-1-5-32-544' -Member 'bob' -ErrorAction SilentlyContinue
# 3) the Guest account is on
Get-LocalUser | Where-Object { $_.SID.Value -like '*-501' } | Enable-LocalUser
# 4) the firewall is off
Set-NetFirewallProfile -Profile Domain, Private, Public -Enabled False
# 5) any password length is accepted
net accounts /minpwlen:0 | Out-Null
if ($LASTEXITCODE -ne 0) { throw "net accounts failed ($LASTEXITCODE)" }
